{"command": "for pkg in "Microsoft.AspNetCore.Mvc.NewtonsoftJson"; do
  curl -s "https://api.nuget.org/v3-flatcontainer/$( echo "$pkg" | tr '[:upper:]' '[:lower:]' )/index.json" | python3 -c "
import sys,json
vs=[v for v in json.load(sys.stdin)['versions'] if '-' not in v]
# latest 6.0.x and 8.0.x
for prefix in ['6.0','8.0']:
  matches=[v for v in vs if v.startswith(prefix)]
  if matches: print(f'{prefix}.x latest: {matches[-1]}')
"
done", "description": "Check TFM-specific package versions"}
